// -----------------------------------------------------------------
// お菓子の魔女の家 — レベルデータ。
// layers[y] は下の段から。各段は奥(z=0)から手前の行。文字は puzzle-core の INFO.char
//   . 空  # クッキー  H 飴  X キャラメル  M しぼり袋  m クリーム  E シュークリーム
//   S マシュマロ  B パチパチ  I ウエハース  r b y グミ  + 大口アメ  = | / ポッキー(x,y,z)
//   W コーヒー  P とうがらし  C とけたチョコ  c チョコだれ
//
// 進行のルール：1ステージで新登場するお菓子は1種だけ（intro）。グミ・ポッキーのように
// 組で使うものは組で1種と数える。新登場したら、そのお菓子が主役のステージを2つ続ける。
// limit は solve.mjs で求めた最短手数（par）に余裕を足したもの
// -----------------------------------------------------------------
(function (root, factory) {
  if (typeof module === "object" && module.exports) module.exports = factory();
  else root.PuzzleLevels = factory();
})(typeof self !== "undefined" ? self : this, function () {
  "use strict";
  const L = (id, name, intro, size, par, limit, hint, layers) => ({ id, name, intro, size, par, limit, hint, layers });
  return [
    // ---- クッキー ----
    L("L01", "はじめのひとくち", "#", [2, 1, 2], 4, 4, "タップでひとくち。ぜんぶ食べればクリア。",
      [["##", "##"]]),

    // ---- パチパチキャンディ ----
    L("L02", "パチパチ", "B", [3, 2, 3], 1, 2, "口の中で弾けて、周りもいっしょに。",
      [["###", "###", "###"],
       ["###", "#B#", "###"]]),
    L("L03", "パチパチはパチパチを呼ぶ", "B", [4, 1, 4], 3, 3, "弾けた先にもう一つあれば、続けて弾ける。",
      [["####", "#B##", "##B#", "####"]]),

    // ---- ウエハース ----
    L("L04", "ウエハース", "I", [4, 1, 4], 1, 1, "隣が崩れると、崩れる。",
      [["IIII", "IIII", "IIII", "IIII"]]),
    L("L05", "四つの角", "I", [5, 1, 5], 5, 5, "つながっていないウエハースには伝わらない。",
      [["IIBII", "II#II", "B###B", "II#II", "IIBII"]]),

    // ---- 飴 ----
    L("L06", "飴", "H", [3, 1, 3], 2, 3, "硬い。2回かじる。",
      [["III", "IHI", "III"]]),
    L("L07", "ひびを入れる", "H", [3, 1, 3], 4, 4, "パチパチで一度ひびを入れれば、もう一度で割れる。",
      [["BHB", "H.H", "BHB"]]),

    // ---- グミ ----
    L("L08", "三つの味", "r", [3, 3, 3], 3, 3, "同じ味は、一つ食べると全部なくなる。",
      [["rby", "byr", "yrb"],
       ["byr", "yrb", "rby"],
       ["yrb", "rby", "byr"]]),
    L("L09", "味の輪", "r", [5, 1, 5], 3, 3, "遠くにあっても同じ味。",
      [["rIIIb", "I...I", "I.y.I", "I...I", "bIIIr"]]),

    // ---- 大口アメ ----
    L("L10", "大口アメ", "+", [3, 3, 3], 2, 3, "なめると、次のひとくちが3×3×3。",
      [["###", "###", "###"],
       ["###", "###", "###"],
       ["...", ".+.", "..."]]),
    L("L11", "二つの箱", "+", [7, 3, 3], 3, 3, "大口アメを巻き込めば、もう一度大口。",
      [["###.###", "###.###", "###.###"],
       ["###.###", "###.###", "###.###"],
       ["+......", ".......", "......+"]]),

    // ---- キャラメル ----
    L("L12", "キャラメル", "X", [3, 1, 3], 1, 2, "歯にくっついてかじれない。巻き込んで食べる。",
      [["XXX", "XBX", "XXX"]]),
    L("L13", "キャラメルの枠", "X", [5, 1, 5], 4, 4, "パチパチの届く範囲を数える。",
      [["XXXXX", "XB.BX", "X...X", "XB.BX", "XXXXX"]]),

    // ---- ポッキー ----
    L("L14", "ポッキー", "=", [5, 1, 5], 2, 3, "矢印の向きに、一直線。",
      [["../..", "..X..", "=XXXX", "..X..", "..X.."]]),
    L("L15", "ポッキーの塔", "=", [5, 4, 5], 1, 2, "一本が一本を呼ぶ。",
      [["=////", "/XXXX", "XXXXX", "XXXXX", "XXXXX"],
       [".....", "X....", ".....", ".....", "....."],
       [".....", "X....", ".....", ".....", "....."],
       [".....", "|....", ".....", ".....", "....."]]),

    // ---- しぼり袋 ----
    // しぼり袋は2つ置く。1つだと初手で食べられて、しぼるところを一度も見ずに終わる
    L("L16", "しぼり袋", "M", [3, 1, 3], 3, 4, "毎ターン、隣にクリームをしぼり出す。",
      [["M.M", ".I.", "..."]]),
    L("L17", "先に止めるのはどっち", "M", [4, 1, 4], 4, 5, "止めるのが先か、食べるのが先か。",
      [["M.II", "..II", "II..", "II.M"]]),
    L("L18", "四隅のしぼり袋", "M", [5, 1, 5], 4, 5, "しぼり袋ごと巻き込む。",
      [["MIIIM", "IB.BI", "I...I", "IB.BI", "MIIIM"]]),

    // ---- シュークリーム ----
    L("L19", "シュークリーム", "E", [3, 2, 3], 3, 4, "3ターンで破裂して、しぼり袋になる。刻みが残りターン。",
      [["III", "IEI", "III"],
       ["...", ".H.", "..."]]),
    L("L20", "四つのシュー", "E", [5, 1, 5], 5, 6, "破裂する前に。",
      [["EIIIE", "IIIII", "IIBII", "IIIII", "EIIIE"]]),

    // ---- ブラックコーヒー ----
    L("L21", "ブラックコーヒー", "W", [3, 1, 3], 1, 2, "飲めば、クリームは全部消える。",
      [["M.M", ".W.", "M.M"]]),
    L("L22", "コーヒーはどこ", "W", [5, 2, 5], 3, 4, "飴の下に何かある。",
      [["IIIII", "IMIMI", "IIWII", "IMIMI", "IIIII"],
       [".....", ".....", "..H..", ".....", "....."]]),

    // ---- マシュマロ ----
    L("L23", "マシュマロ", "S", [5, 1, 1], 1, 2, "かじるとちぎれて増える。ポッキーで一気に。",
      [["SS=SS"]]),
    L("L24", "マシュマロの畑", "S", [5, 1, 5], 3, 4, "直接かじらない。",
      [["SS=SS", ".....", "S.=.S", ".....", "SS=SS"]]),

    // ---- とうがらしチョコ ----
    L("L25", "とうがらしチョコ", "P", [3, 1, 3], 2, 3, "辛い。水を飲むあいだに1ターン過ぎる。最後に食べれば平気。",
      [["MII", "I.I", "IIP"]]),
    L("L26", "辛いのは後で", "P", [5, 1, 5], 5, 6, "水を飲んでいるあいだに、シュークリームが破裂する。",
      [["EIIIE", "I.P.I", "IPBPI", "I.P.I", "EIIIE"]]),

    // ---- とけたチョコ ----
    // チョコも2つ。上に何か被せると隠れてしまい、たれるところが見えない
    L("L27", "とけたチョコ", "C", [3, 3, 3], 5, 6, "毎ターン、下へたれる。",
      [["...", "...", "..."],
       ["I.I", "...", "I.I"],
       [".C.", "...", ".C."]]),
    L("L28", "チョコの棚", "C", [3, 3, 3], 2, 3, "たれる前に、まとめて。",
      [["III", "III", "III"],
       ["...", "...", "..."],
       ["+..", "CCC", "..."]]),

    // ---- 総合 ----
    L("L29", "順番", null, [5, 2, 5], 3, 3, "大口アメを2つ同時になめると5×5×5。",
      [["I+I+I", "IIBII", "IIIII", "SS=SS", ".XXX."],
       [".....", ".....", ".....", ".....", "..#.."]]),
    L("L30", "魔女の家", null, [6, 2, 6], 5, 6, "魔女が帰る前に、全部。",
      [["EIIIIE", "ISBBSI", "IB++BI", "IB++BI", "ISBBSI", "EIIIIE"],
       ["......", "......", "..HH..", "..HH..", "......", "......"]]),
  ];
});
